<script lang="ts">let filter=$state('All'); const notices=[['Enquiry Updates','Your MCA enquiry is now under review.','Today',true],['Counselling Updates','Your counselling session has been scheduled.','Yesterday',true],['Application Updates','Your application status has been updated.','12 Sep',false],['General Notifications','Keep your profile details current for smoother communication.','10 Sep',false]]; let list=$derived(filter==='All'?notices:notices.filter(x=>x[0]===filter));</script><div class="max-w-3xl space-y-6"><div><h1 class="text-3xl font-bold text-white">Notifications</h1><p class="text-text-secondary mt-2">Stay informed about your admission journey.</p></div><div class="flex flex-wrap gap-2">{#each ['All','Enquiry Updates','Counselling Updates','Application Updates'] as item}<button onclick={()=>filter=item} class:active={filter===item} class="filter">{item}</button>{/each}</div><div class="space-y-3">{#each list as n}<article class:unread={n[3]} class="bg-card border border-white/10 rounded-2xl p-5 flex gap-4"><span class="w-10 h-10 rounded-xl bg-accent/15 text-accent grid place-items-center">●</span><div class="flex-1"><div class="flex justify-between gap-4"><h2 class="text-white font-medium">{n[0]}</h2><time class="text-xs text-text-secondary">{n[2]}</time></div><p class="text-sm text-text-secondary mt-2">{n[1]}</p></div>{#if n[3]}<span class="w-2 h-2 bg-accent rounded-full"></span>{/if}</article>{/each}</div></div><style>.filter{padding:.45rem .75rem;border:1px solid rgba(255,255,255,.1);border-radius:.6rem;color:#a7a4b4;font-size:.75rem}.filter.active{color:white;border-color:rgba(164,123,224,.5);background:rgba(164,123,224,.12)}.unread{border-color:rgba(164,123,224,.25)}</style>
